    public void testSomeWhereAllowSetsDoneAndExplainIndexAndEffect() throws Exception {
        DefaultStreamEffector eff = new DefaultStreamEffector("some(where (p_eft == allow))");
        int idx = 5;
        boolean result = eff.push(Effect.Allow, idx, 10);
        assertTrue(result);
        assertTrue(getBoolean(eff, "done"));
        assertTrue(getBoolean(eff, "effect"));
        assertEquals(idx, getInt(eff, "explainIndex"));
    }

