    public void testNotSomeDenyAllowsAndSetsForDeny() throws Exception {
        // Test Deny branch
        DefaultStreamEffector eff1 = new DefaultStreamEffector("!some(where (p_eft == deny))");
        int idx1 = 3;
        boolean res1 = eff1.push(Effect.Deny, idx1, 0);
        assertTrue(res1);
        assertFalse(getBoolean(eff1, "effect"));
        assertTrue(getBoolean(eff1, "done"));
        assertEquals(idx1, getInt(eff1, "explainIndex"));

        // Test Allow path when not Deny
        DefaultStreamEffector eff2 = new DefaultStreamEffector("!some(where (p_eft == deny))");
        int idx2 = 4;
        boolean res2 = eff2.push(Effect.Allow, idx2, 0);
        assertFalse(res2);
        assertTrue(getBoolean(eff2, "effect"));
        // explainIndex should remain default (-1)
        assertEquals(-1, getInt(eff2, "explainIndex"));
    }

    @Test
    public void testSomeAllowAndDenyInCombo() throws Exception {
        DefaultStreamEffector eff = new DefaultStreamEffector("some(where (p_eft == allow)) && !some(where (p_eft == deny))");
        int idx1 = 7;
        boolean resAllow = eff.push(Effect.Allow, idx1, 0);
        assertFalse(resAllow);
        assertTrue(getBoolean(eff, "effect"));
        assertEquals(idx1, getInt(eff, "explainIndex"));

        int idx2 = 9;
        boolean resDeny = eff.push(Effect.Deny, idx2, 0);
        assertTrue(resDeny);
        assertFalse(getBoolean(eff, "effect"));
        assertEquals(idx2, getInt(eff, "explainIndex"));
        assertTrue(getBoolean(eff, "done"));
