import java.util.*;

import static org.junit.Assert.*;

public class LoadPolicyLineTests {

    private Model createModelWithPSection() {
        Model model = new Model();
        Map<String, Map<String, Assertion>> m = new HashMap<>();
        Map<String, Assertion> pSection = new HashMap<>();
        Assertion p = new Assertion();
        p.policy = new ArrayList<>();
        p.policyIndex = new HashMap<>();
        pSection.put("p", p);
        m.put("p", pSection);
        model.model = m;
        return model;
    }

    @Test
    public void testLoadPolicyLine_EmptyLine() {
        Model model = new Model();
        model.model = new HashMap<>();

        load("","model should not crash", model);
        assertTrue(model.model.isEmpty());
    }

    @Test
    public void testLoadPolicyLine_CommentLine() {
        Model model = new Model();
        model.model = new HashMap<>();

        load("# this is a comment", "model should ignore comments", model);
        assertTrue(model.model.isEmpty());
    }

    @Test
    public void testLoadPolicyLine_AddPolicy() {
        Model model = createModelWithPSection();

        Helper.loadPolicyLine("p, alice, data1, read", model);

        Assertion ast = model.model.get("p").get("p");
        assertNotNull(ast);
        assertEquals(1, ast.policy.size());

        List<String> expected = Arrays.asList("alice", "data1", "read");
        assertEquals(expected, ast.policy.get(0));

        String key = expected.toString();
        assertEquals(Integer.valueOf(0), ast.policyIndex.get(key));
    }

