        Model model = new Model();
        Map<String, Map<String, Assertion>> m = new HashMap<>();
        Map<String, Assertion> pSection = new HashMap<>();
        // Do not put "p" key inside to ensure ast is null
        m.put("p", pSection);
        model.model = m;

        Helper.loadPolicyLine("p, alice, data1, read", model);

        // Since ast is null, the inner map should remain without "p" key
        assertFalse(pSection.containsKey("p"));
    }

    @Test
    public void testLoadPolicyLine_MultipleAdds() {
        Model model = createModelWithPSection();

        Helper.loadPolicyLine("p, alice, data1, read", model);
        Helper.loadPolicyLine("p, bob, data2, write", model);

        Assertion ast = model.model.get("p").get("p");
        assertNotNull(ast);
