            try {
                Field f = cls.getDeclaredField(fieldName);
                f.setAccessible(true);
                f.set(target, value);
                return;
            } catch (NoSuchFieldException e) {
                cls = cls.getSuperclass();
            }
        }
        throw new NoSuchFieldException(fieldName);
    }

    // Create a dynamic proxy that implements UpdatableAdapter with controllable behavior
    private UpdatableAdapter createUpdatableAdapterProxy(boolean throwOnUpdate, AtomicReference<String> lastSecRef, AtomicReference<String> lastPtypeRef, AtomicReference<List<String>> lastOldRef, AtomicReference<List<String>> lastNewRef) {
        InvocationHandler handler = new InvocationHandler() {
            @Override
            public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                if ("updatePolicy".equals(method.getName())) {
                    String sec = (String) args[0];
                    String ptype = (String) args[1];
                    @SuppressWarnings("unchecked")
                    List<String> oldRule = (List<String>) args[2];
                    @SuppressWarnings("unchecked")
                    List<String> newRule = (List<String>) args[3];
                    if (throwOnUpdate) {
                        throw new RuntimeException("boom");
                    }
                    if (lastSecRef != null) lastSecRef.set(sec);
                    if (lastPtypeRef != null) lastPtypeRef.set(ptype);
                    if (lastOldRef != null) lastOldRef.set(oldRule);
                    if (lastNewRef != null) lastNewRef.set(newRule);
                    return null;
                }
                // Other methods of UpdatableAdapter/Adapter are not used in tests
                return null;
            }
        };
        return (UpdatableAdapter) Proxy.newProxyInstance(
                UpdatableAdapter.class.getClassLoader(),
                new Class[]{UpdatableAdapter.class},
                handler);
    }

    @Test
