package org.casbin.jcasbin.main;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class StartAutoLoadPolicyTests {

    public static class CountingSyncedEnforcer extends SyncedEnforcer {
        private final AtomicInteger loadCount = new AtomicInteger(0);

        public CountingSyncedEnforcer() {
            super();
        }

        @Override
        public void loadPolicy() {
            loadCount.incrementAndGet();
        }

        public int getLoadCount() {
            return loadCount.get();
        }
    }

    @Test
    public void testStartAutoLoadPolicyStartsAndStops() throws Exception {
        CountingSyncedEnforcer enforcer = new CountingSyncedEnforcer();
        enforcer.startAutoLoadPolicy(20);

        long start = System.currentTimeMillis();
        while (enforcer.getLoadCount() < 3 && System.currentTimeMillis() - start < 3000) {
            Thread.sleep(5);
        }

        assertTrue("Should have loaded policy at least 3 times", enforcer.getLoadCount() >= 3);

        Thread blocker = null;
        Map<Thread, StackTraceElement[]> all = Thread.getAllStackTraces();
        for (Thread t : all.keySet()) {
            if (t == Thread.currentThread()) continue;
            if (!t.isAlive()) continue;
            StackTraceElement[] st = t.getStackTrace();
            boolean found = false;
            for (StackTraceElement se : st) {
                String m = se.getMethodName();
                if (m != null && m.startsWith("lambda$startAutoLoadPolicy$")) {
                    found = true;
                    break;
                }
            }
            if (found) {
                blocker = t;
                break;
            }
        }

        if (blocker == null) {
            // Fallback: try to locate by SyncedEnforcer references
            for (Thread t : Thread.getAllStackTraces().keySet()) {
                if (t == Thread.currentThread()) continue;
                if (!t.isAlive()) continue;
                StackTraceElement[] st = t.getStackTrace();
                for (StackTraceElement se : st) {
                    if (se.getClassName().contains("SyncedEnforcer") && se.getMethodName().equals("startAutoLoadPolicy")) {
                        blocker = t;
                        break;
                    }
                }
                if (blocker != null) break;
            }
        }

        if (blocker != null) {
            blocker.interrupt();
            blocker.join(1000);
            assertFalse("Background thread should terminate", blocker.isAlive());
        } else {
            fail("Could not locate the auto-load background thread to interrupt");
        }
    }

    @Test
    public void testStartAutoLoadPolicyCanRestartAfterInterrupt() throws Exception {
        CountingSyncedEnforcer enforcer = new CountingSyncedEnforcer();
        enforcer.startAutoLoadPolicy(15);

        long start = System.currentTimeMillis();
        while (enforcer.getLoadCount() < 2 && System.currentTimeMillis() - start < 3000) {
            Thread.sleep(5);
