package org.casbin.jcasbin.main;

import org.casbin.jcasbin.persist.DefaultCache;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.junit.Assert.*;

public class RemovePolicyTests {

    // RecordingCache to capture delete calls
    static class RecordingCache extends DefaultCache {
        public String lastDeletedKey;

        @Override
        public void delete(String key) {
            lastDeletedKey = key;
        }
    }

    private void setEnableCache(CachedEnforcer enforcer, boolean value) {
        Class<?> cls = enforcer.getClass();
        while (cls != null) {
            try {
                Field f = cls.getDeclaredField("enableCache");
                f.setAccessible(true);
                Object obj = f.get(enforcer);
                if (obj instanceof AtomicBoolean) {
                    ((AtomicBoolean) obj).set(value);
                }
                return;
            } catch (NoSuchFieldException | IllegalAccessException e) {
                cls = cls.getSuperclass();
            }
        }
    }

    private boolean setCacheField(CachedEnforcer enforcer, RecordingCache recCache) {
        Class<?> cls = enforcer.getClass();
        while (cls != null) {
            try {
                Field f = cls.getDeclaredField("cache");
                f.setAccessible(true);
                f.set(enforcer, recCache);
                return true;
            } catch (NoSuchFieldException | IllegalAccessException e) {
                cls = cls.getSuperclass();
            }
        }
        return false;
    }

    @Test
    public void testRemovePolicy_CachesWhenEnabled() {
        CachedEnforcer enforcer = new CachedEnforcer();
        RecordingCache rec = new RecordingCache();
        setCacheField(enforcer, rec);
        setEnableCache(enforcer, true);

        enforcer.removePolicy("p", "alice", "data1", "read");

        assertNotNull("Cache delete should be called when enabled and key is non-null", rec.lastDeletedKey);
    }

    @Test
    public void testRemovePolicy_DoesNotCacheWhenDisabled() {
        CachedEnforcer enforcer = new CachedEnforcer();
        RecordingCache rec = new RecordingCache();
        setCacheField(enforcer, rec);
        setEnableCache(enforcer, false);

        enforcer.removePolicy("p", "alice", "data1", "read");

        assertNull("Cache delete should not be called when caching is disabled", rec.lastDeletedKey);
    }
}

