package org.casbin.jcasbin.rbac;

import org.junit.Test;
import static org.junit.Assert.*;

import java.util.*;

public class RangeRolesTests {

    @Test
    public void testRangeRoles_basicTraversal() {
        Role root = new Role("root");

        Role a = new Role("A");
        Role b = new Role("B");
        Role c = new Role("C");

        root.roles.put("A", a);
        root.roles.put("B", b);

        a.matched.put("c", c);

        final List<Role> visited = new ArrayList<>();
        root.rangeRoles(r -> visited.add(r));

        Set<Role> expected = new HashSet<>(Arrays.asList(a, b, c));
        Set<Role> actual = new HashSet<>(visited);
        assertEquals(expected, actual);
    }

    @Test
    public void testRangeRoles_matchedByTraversal() {
        Role root = new Role("root2");

        Role inner1 = new Role("Inner1");
        Role inner2 = new Role("Inner2");

        Role parent = new Role("Parent");
        parent.roles.put("Inner1", inner1);
        parent.roles.put("Inner2", inner2);

        root.matchedBy.put("p", parent);

        final List<Role> visited = new ArrayList<>();
        root.rangeRoles(r -> visited.add(r));

        Set<Role> expected = new HashSet<>(Arrays.asList(inner1, inner2));
        Set<Role> actual = new HashSet<>(visited);
        assertEquals(expected, actual);
    }

    @Test
    public void testRangeRoles_combinedTraversal() {
        Role root = new Role("root3");

        Role r1 = new Role("R1");
        Role r1Matched = new Role("R1-Matched");
        r1.matched.put("mX", r1Matched);

        Role rX_inner1 = new Role("Inner1");
        Role rX_inner2 = new Role("Inner2");
        Role rX = new Role("R1-Parent");
        rX.roles.put("Inner1", rX_inner1);
        rX.roles.put("Inner2", rX_inner2);

        root.roles.put("R1", r1);
        root.matchedBy.put("p2", rX);

        final List<Role> visited = new ArrayList<>();
        root.rangeRoles(r -> visited.add(r));

        Set<Role> expected = new HashSet<>(Arrays.asList(r1, r1Matched, rX_inner1, rX_inner2));
        Set<Role> actual = new HashSet<>(visited);
        assertEquals(expected, actual);
    }
}

