package org.casbin.jcasbin.main;

import org.casbin.jcasbin.cache.DefaultCache;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;

public class RemovePoliciesTests {

    public static class TestCache extends DefaultCache {
        public List<String> deletes = new ArrayList<>();

        @Override
        public void delete(String key) {
            deletes.add(key);
            super.delete(key);
        }
    }

    private Field findField(Object obj, String name) {
        Class<?> cls = obj.getClass();
        while (cls != null) {
            try {
                Field f = cls.getDeclaredField(name);
                f.setAccessible(true);
                return f;
            } catch (NoSuchFieldException e) {
                cls = cls.getSuperclass();
            }
        }
        throw new RuntimeException("Field not found: " + name);
    }

    private void injectField(Object target, String fieldName, Object value) {
        Field f = findField(target, fieldName);
        try {
            f.set(target, value);
        } catch (IllegalAccessException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testRemovePolicies_CachesKeysWhenRulesAndCacheEnabled() throws Exception {
        CachedEnforcer ce = new CachedEnforcer();

        TestCache testCache = new TestCache();
        injectField(ce, "cache", testCache);

        // Enable cache
        injectField(ce, "enableCache", new AtomicBoolean(true));

        String[][] rules = new String[][]{
                new String[]{"p", "alice", "data1", "read"},
                new String[]{"p", "bob", "data2", "write"}
        };

        ce.removePolicies(rules);

        assertEquals("Cache should have recorded two deletions", 2, testCache.deletes.size());
        for (String key : testCache.deletes) {
            assertNotNull("Deleted key should not be null", key);
            assertFalse("Deleted key should not be empty", key.isEmpty());
        }
    }

    @Test
    public void testRemovePolicies_DoesNotDeleteWhenRulesNull() throws Exception {
        CachedEnforcer ce = new CachedEnforcer();
        TestCache testCache = new TestCache();
        injectField(ce, "cache", testCache);
        injectField(ce, "enableCache", new AtomicBoolean(true));

        ce.removePolicies(null);

        assertEquals("No deletions should occur when rules are null", 0, testCache.deletes.size());
    }

    @Test
    public void testRemovePolicies_DoesNotDeleteWhenCacheDisabled() throws Exception {
        CachedEnforcer ce = new CachedEnforcer();
        TestCache testCache = new TestCache();
        injectField(ce, "cache", testCache);
        injectField(ce, "enableCache", new AtomicBoolean(false));

        String[][] rules = new String[][]{
                new String[]{"p", "alice", "data1", "read"},
                new String[]{"p", "bob", "data2", "write"}
        };

        ce.removePolicies(rules);

        assertEquals("No deletions should occur when cache is disabled", 0, testCache.deletes.size());
    }
}

