import static org.junit.Assert.*;

public class RemoveRoleTests {

    @Test
    public void testRemoveRoleRemovesExistingRole() throws Exception {
        DefaultRoleManager rm = new DefaultRoleManager(2);

        // Access private allRoles field
        Field field = DefaultRoleManager.class.getDeclaredField("allRoles");
        field.setAccessible(true);
        Map<String, Object> allRoles = (Map<String, Object>) field.get(rm);

        // Find inner class Role
        Class<?> roleClass = null;
        for (Class<?> c : DefaultRoleManager.class.getDeclaredClasses()) {
            if ("Role".equals(c.getSimpleName())) {
                roleClass = c;
                break;
            }
        }
        assertNotNull("Role inner class not found", roleClass);

        // Find suitable constructor for Role
        Constructor<?> ctor = null;
        for (Constructor<?> c : roleClass.getDeclaredConstructors()) {
            Class<?>[] params = c.getParameterTypes();
            if (params.length == 1 && params[0] == String.class) {
                ctor = c;
                break;
            }
            if (params.length == 2 &&
                    ((params[0] == String.class && params[1] == DefaultRoleManager.class) ||
                     (params[0] == DefaultRoleManager.class && params[1] == String.class))) {
                ctor = c;
                break;
            }
        }
        assertNotNull("No suitable Role constructor found", ctor);
        ctor.setAccessible(true);

        Object roleInstance;
        Class<?>[] ptypes = ctor.getParameterTypes();
        if (ptypes.length == 1) {
            roleInstance = ctor.newInstance("alice");
        } else if (ptypes.length == 2) {
            if (ptypes[0] == String.class && ptypes[1] == DefaultRoleManager.class) {
                roleInstance = ctor.newInstance("alice", rm);
            } else {
                roleInstance = ctor.newInstance(rm, "alice");
            }
        } else {
            roleInstance = ctor.newInstance();
        }

        // Insert role into allRoles using reflection
        Method put = allRoles.getClass().getMethod("put", Object.class, Object.class);
        put.invoke(allRoles, "alice", roleInstance);
        assertTrue("Role should be added to internal map", allRoles.containsKey("alice"));

        // Act
        rm.removeRole("alice");

        // Assert
        assertFalse("Role should be removed from internal map", allRoles.containsKey("alice"));
    }

    @Test
    public void testRemoveRoleWithNonExistingRoleDoesNothing() throws Exception {
        DefaultRoleManager rm = new DefaultRoleManager(2);

        // Access private allRoles field
        Field field = DefaultRoleManager.class.getDeclaredField("allRoles");
        field.setAccessible(true);
        Map<String, Object> allRoles = (Map<String, Object>) field.get(rm);

        // Ensure key does not exist
        assertFalse(allRoles.containsKey("nonexistent"));

        // Act
        rm.removeRole("nonexistent");

        // Assert
        assertFalse(allRoles.containsKey("nonexistent"));
    }
