package org.casbin.jcasbin.main;

import org.junit.Assert;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

public class EnforceTests {

    // Test 1: Cache disabled should use super.enforce
    @Test
    public void testEnforce_CacheDisabled_ShouldCallSuperEnforce() throws Exception {
        MockCachedEnforcer enforcer = new MockCachedEnforcer();

        // Disable cache via reflection
        Field f = CachedEnforcer.class.getDeclaredField("enableCache");
        f.setAccessible(true);
        Object obj = f.get(enforcer);
        if (obj instanceof AtomicBoolean) {
            ((AtomicBoolean) obj).set(false);
        }

        boolean result = enforcer.enforce("user", "data", "action");
        // Without policies, enforcement should fail (false)
        Assert.assertFalse("Expected false when no policies and cache disabled", result);
    }

    // Test 2: Key is null should bypass cache and go to super.enforce
    @Test
    public void testEnforce_KeyNull_ShouldCallSuperEnforce() {
        MockCachedEnforcer enforcer = new MockCachedEnforcer();
        enforcer.testKey = null; // getKey will return null

        boolean result = enforcer.enforce("user", "data", "action");
        // Without policies, enforcement should fail (false)
        Assert.assertFalse("Expected false when key is null (no cache), no policies", result);
    }

    // Test 3: Cache hit should return cached value without calling setCachedResult
    @Test
    public void testEnforce_CacheHit_ShouldReturnCachedValue() {
        MockCachedEnforcer enforcer = new MockCachedEnforcer();
        enforcer.testKey = "K";

        // Seed cache with true
        enforcer.cache.put("K", true);

        boolean result = enforcer.enforce("user", "data", "action");
        Assert.assertTrue("Expected cached value to be returned", result);
        Assert.assertEquals("setCachedResult should not have been called on cache hit", 0, enforcer.setCalls);
    }

    // Test 4: Cache miss should populate cache
    @Test
    public void testEnforce_CacheMiss_ShouldPopulateCache() {
        MockCachedEnforcer enforcer = new MockCachedEnforcer();
        enforcer.testKey = "L";

        // Ensure cache is empty
        enforcer.cache.clear();

        boolean result = enforcer.enforce("user", "data", "action");
        // Since there are no policies, result should be false and cache should be populated
        Assert.assertFalse("Expected false on cache miss with no policies", result);
        Assert.assertEquals("Cache should have been populated once", 1, enforcer.setCalls);
        Assert.assertEquals("Cached key should be", "L", enforcer.lastSetKey);
        Assert.assertFalse("Cached value should be false on miss", enforcer.lastSetValue);
        Assert.assertTrue("Expire time should be non-negative", enforcer.lastExpireTime >= 0);
    }

    // Test 5: Second call should use cached value (no additional setCachedResult call)
    @Test
    public void testEnforce_CacheHitOnSecondCall_ShouldUseCache() {
        MockCachedEnforcer enforcer = new MockCachedEnforcer();
        enforcer.testKey = "M";

        // First call: cache miss, will populate
        enforcer.cache.clear();
        boolean firstResult = enforcer.enforce("user", "data", "action");
        Assert.assertFalse("First call expected to be false (no policies)", firstResult);
        Assert.assertEquals("Cache should have been populated once", 1, enforcer.setCalls);

        // Second call: should hit cache
        boolean secondResult = enforcer.enforce("user", "data", "action");
        Assert.assertFalse("Second call should return cached value", secondResult);
        // setCachedResult should not be called again
        Assert.assertEquals("setCachedResult should not be called on cache hit", 1, enforcer.setCalls);
    }

    // Mock CachedEnforcer to control getKey, getCachedResult and setCachedResult
    public static class MockCachedEnforcer extends CachedEnforcer {
        public String testKey = "DEFAULT";
        public Map<String, Boolean> cache = new HashMap<>();
        public int setCalls = 0;
        public String lastSetKey;
        public boolean lastSetValue;
        public long lastExpireTime;

        public MockCachedEnforcer() {
            super();
        }

        @Override
        protected String getKey(Object... rvals) {
            return testKey;
        }

        @Override
        protected Boolean getCachedResult(String key) {
            return cache.containsKey(key) ? cache.get(key) : null;
        }

        @Override
        protected void setCachedResult(String key, boolean result, long expireTime) {
            cache.put(key, result);
            lastSetKey = key;
            lastSetValue = result;
            lastExpireTime = expireTime;
            setCalls++;
        }
    }
}

