import java.util.function.BiPredicate;

package org.casbin.jcasbin.rbac;

public class MatchTests {

    @Test
    public void testMatchWithCustomPredicateCachesResults() {
        final int[] counter = new int[1];
        BiPredicate<String, String> pred = new BiPredicate<String, String>() {
            @Override
            public boolean test(String s, String p) {
                counter[0]++;
                return s != null && s.equals(p);
            }
        };

        DefaultRoleManager drm = new DefaultRoleManager(10, pred, null);
        assertTrue("Expected match of identical strings with custom predicate", drm.match("foo","foo"));
        assertEquals("Predicate should have been invoked once", 1, counter[0]);

        assertFalse("Expected non-matching pair should be false with custom predicate", drm.match("foo","bar"));
        assertEquals("Predicate should have been invoked second time for new pair", 2, counter[0]);

        // Cached result for same pair should not invoke predicate again
        assertTrue("Cached result should be true for matching pair", drm.match("foo","foo"));
        assertEquals("Predicate should not be invoked for cached result", 2, counter[0]);

        // Ensure another new pair adds to call count
        assertFalse("Another new pair should evaluate via predicate", drm.match("bar","baz"));
        assertEquals("Predicate should have been invoked for new pair", 3, counter[0]);
    }

    @Test
    public void testMatchWithNullPredicateUsesEqualsAndCache() {
        DefaultRoleManager drm = new DefaultRoleManager(10, null, null);
        // Should use equals
        assertTrue("Expected equal strings to match", drm.match("alice","alice"));
        // Cached result should be reused for same input
        assertTrue("Expected cached result to be true for equal strings", drm.match("alice","alice"));

        // Different strings should not match
        assertFalse("Expected non-equal strings to not match", drm.match("alice","bob"));

        // Cached for non-match
        assertFalse("Expected cached non-match result for same pair", drm.match("alice","bob"));
    }
