import java.util.HashMap;
import java.util.Map;
import java.util.function.BiPredicate;

import static org.mockito.Mockito.*;

public class DeleteLinkTests {

    // Subclass to override getRoleManager and to expose internal maps for testing
    static class TestDomainManager extends DomainManager {
        public Map<String, DefaultRoleManager> roleMap = new HashMap<>();

        TestDomainManager(int maxHierarchyLevel, BiPredicate<String, String> matchingFunc,
                          BiPredicate<String, String> domainMatchingFunc) {
            super(maxHierarchyLevel, matchingFunc, domainMatchingFunc);
        }

        @Override
        protected DefaultRoleManager getRoleManager(String domain, boolean create) {
            return roleMap.computeIfAbsent(domain, d -> Mockito.mock(DefaultRoleManager.class));
        }
    }

    // Helper to insert into rmMap via reflection (rmMap is private in DomainManager)
    private void putIntoRmMap(DomainManager dm, String domain2, DefaultRoleManager rm) throws Exception {
        Field field = DomainManager.class.getDeclaredField("rmMap");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<String, DefaultRoleManager> map = (Map<String, DefaultRoleManager>) field.get(dm);
        map.put(domain2, rm);
    }

    @Test
    public void testDeleteLink_crossDomain_callsAll() throws Exception {
        // domainMatchingFunc returns true to simulate matching across domains
        TestDomainManager dm = new TestDomainManager(3, null, (d1, d2) -> true);

        // Create and insert a second domain's RM into rmMap
        DefaultRoleManager rm2 = mock(DefaultRoleManager.class);
        putIntoRmMap(dm, "domainB", rm2);

        // Invoke code under test
        dm.deleteLink("u1", "u2", "domainA");

        // Verify primary domain's role manager deleteLink called
        DefaultRoleManager rmA = dm.roleMap.get("domainA");
        verify(rmA).deleteLink(eq("u1"), eq("u2"), Mockito.<String[]>any());

        // Verify cross-domain call also happened for domainB's RM
        verify(rm2).deleteLink(eq("u1"), eq("u2"), Mockito.<String[]>any());
    }

    @Test
    public void testDeleteLink_noCrossDomain_whenDomainMatchingFuncNull() throws Exception {
        // domainMatchingFunc is null, so cross-domain delete should not occur
        TestDomainManager dm = new TestDomainManager(3, null, null);

        // Insert a second domain's RM into rmMap
        DefaultRoleManager rm2 = mock(DefaultRoleManager.class);
        putIntoRmMap(dm, "domainB", rm2);

        // Invoke code under test
        dm.deleteLink("u1", "u2", "domainA");

        // Verify primary domain's role manager deleteLink called
        DefaultRoleManager rmA = dm.roleMap.get("domainA");
        verify(rmA).deleteLink(eq("u1"), eq("u2"), Mockito.<String[]>any());

        // Verify cross-domain deleteLink was not called
        verify(rm2, never()).deleteLink(anyString(), anyString(), any(String[].class));
    }
